    R2 = DM(23, I7);
    R1 = LSHIFT R1 BY 3;                                // index = x + y * 8 + z * 64
    R2 = LSHIFT R2 BY 6;
    .NOCOMPRESS;
    R0 = R0 + R1;
    .COMPRESS;
    .NOCOMPRESS;
    R0 = R0 + R2;
    .COMPRESS;
    R0 = LSHIFT R0 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R14;
    .COMPRESS;
    I4 = R0;
    R2 = DM(19, I7);
    R3 = 0;                                             // (DAG gap)
    R4 = 0;
    R1 = DM(I4, M5);                                    // wave_map_[index]
    .NOCOMPRESS;
    R1 = R1 + R2;                                       // + p_integral
    .COMPRESS;
    R1 = LSHIFT R1 BY 2;
    .NOCOMPRESS;
    R1 = R1 + R15;
    .COMPRESS;
    I4 = R1;
    R8 = 0x3F000000;                                    // half
    R3 = 0;                                             // (DAG gap)
    R4 = 0;
    R4 = DM(I4, M5);                                    // xm1
    R5 = DM(1, I4);                                     // x0
    R6 = DM(2, I4);                                     // x1
    R7 = DM(3, I4);                                     // x2
    F0 = F6 - F4;                                       // c = (x1 - xm1) * 0.5f
    F0 = F0 * F8;
    F1 = F5 - F6;                                       // v = x0 - x1
    F2 = F0 + F1;                                       // w = c + v
    F3 = F7 - F5;                                       // a = w + v + (x2 - x0) * 0.5f
    F3 = F3 * F8;
    F4 = F2 + F1;
    F3 = F4 + F3;
    F2 = F2 + F3;                                       // b_neg = w + a
    F3 = F3 * F12;                                      // (((a * pf) - b_neg) * pf + c) * pf + x0
    F3 = F3 - F2;
    F3 = F3 * F12;
    F3 = F3 + F0;
    F3 = F3 * F12;
    F3 = F3 + F5;
    DM(33, I7) = R3;
    R8 = DM(16, I7);
    R0 = DM(26, I7);
    R1 = DM(27, I7);
    F2 = F1 - F0;
    F2 = F2 * F8;
    F2 = F0 + F2;
    DM(26, I7) = R2;                                    // xy0z0
    R0 = DM(28, I7);
    R1 = DM(29, I7);
    F2 = F1 - F0;
    F2 = F2 * F8;
    F2 = F0 + F2;
    DM(28, I7) = R2;                                    // xy1z0
    R0 = DM(30, I7);
    R1 = DM(31, I7);
    F2 = F1 - F0;
    F2 = F2 * F8;
    F2 = F0 + F2;
    DM(30, I7) = R2;                                    // xy0z1
    R0 = DM(32, I7);
    R1 = DM(33, I7);
    F2 = F1 - F0;
    F2 = F2 * F8;
    F2 = F0 + F2;
    DM(32, I7) = R2;                                    // xy1z1
    R8 = DM(17, I7);
    R0 = DM(26, I7);
    R1 = DM(28, I7);
    F4 = F1 - F0;
    F4 = F4 * F8;
    F4 = F0 + F4;
    R0 = DM(30, I7);
    R1 = DM(32, I7);
    F5 = F1 - F0;
    F5 = F5 * F8;
    F5 = F0 + F5;
    R8 = DM(18, I7);
    F6 = F5 - F4;
    F6 = F6 * F8;
    F6 = F4 + F6;
    F0 = F6 - F10;                                      // ONE_POLE(d_lp, mix - d_previous, cutoff)
    F0 = F0 - F11;
    R1 = DM(15, I7);
    F0 = F1 * F0;
    F11 = F11 + F0;
    R10 = PASS R6;                                      // d_previous = mix
    R1 = DM(14, I7);
    F0 = F11 * F1;                                      // mix = d_lp * gain
    DM(I0, M6) = R0;
    R1 = 0x42000000;                                    // 32
    F2 = F0 * F1;                                       // aux = itof_small((int)(mix * 32.0f)) / 32.0f
    R2 = TRUNC F2;
    R3 = 0x4B400000;                                    // 1.5x2^23
    .NOCOMPRESS;
    R2 = R3 + R2;
    .COMPRESS;
    F2 = F2 - F3;
    R4 = DM(13, I7);
    F5 = F2 * F4;                                       // / 32.0f: q
    F6 = F1 * F5;
    F6 = F2 - F6;
    F6 = F6 * F4;
    F5 = F5 + F6;
    DM(I1, M6) = R5;
    R0 = DM(12, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(12, I7) = R0;
    IF NE JUMP _wek_loop;
_wek_done:
    DM(11, I2) = R11;
    DM(12, I2) = R10;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,33)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
